//==============================================================================
// RISC-V RV32I 5-stage pipelined CPU
//==============================================================================

module riscv_cpu (
    input  wire        clk,
    input  wire        rst_n,

    // Instruction Memory Interface
    output wire [31:0] imem_addr,
    input  wire [31:0] imem_data,

    // Data Memory Interface
    output wire [31:0] dmem_addr,
    output wire [31:0] dmem_wdata,
    output wire        dmem_wen,
    output wire [3:0]  dmem_be,
    input  wire [31:0] dmem_rdata,

    // Debug Interface
    output wire [31:0] debug_pc,
    output wire [31:0] debug_inst
);

    // =====================================================================
    // ALU operation encoding
    // =====================================================================
    localparam [3:0] ALU_ADD = 4'b0000;
    localparam [3:0] ALU_SUB = 4'b0001;
    localparam [3:0] ALU_AND = 4'b0010;
    localparam [3:0] ALU_OR  = 4'b0011;
    localparam [3:0] ALU_XOR = 4'b0100;
    localparam [3:0] ALU_SLT = 4'b0101;
    localparam [3:0] ALU_SLL = 4'b0110;
    localparam [3:0] ALU_SRL = 4'b0111;
    localparam [3:0] ALU_SRA = 4'b1000;

    // =====================================================================
    // PC
    // =====================================================================
    reg  [31:0] pc;
    wire [31:0] pc_plus4 = pc + 32'd4;

    assign imem_addr  = pc;
    assign debug_pc   = pc;
    assign debug_inst = imem_data;

    // =====================================================================
    // IF/ID pipeline register
    // =====================================================================
    reg [31:0] ifid_pc;
    reg [31:0] ifid_inst;
    reg        ifid_valid;

    // =====================================================================
    // ID/EX pipeline register
    // =====================================================================
    reg [31:0] idex_pc;
    reg [31:0] idex_rs1_data;
    reg [31:0] idex_rs2_data;
    reg [4:0]  idex_rs1;
    reg [4:0]  idex_rs2;
    reg [4:0]  idex_rd;
    reg [31:0] idex_imm;
    reg        idex_regwrite;
    reg        idex_memread;
    reg        idex_memwrite;
    reg        idex_alusrc;
    reg        idex_branch;
    reg        idex_jump;
    reg        idex_jalr;
    reg [3:0]  idex_alu_op;
    reg [2:0]  idex_funct3;
    reg        idex_valid;

    // =====================================================================
    // EX/MEM pipeline register
    // =====================================================================
    reg [31:0] exmem_alu_result;
    reg [31:0] exmem_mem_data;
    reg [4:0]  exmem_rd;
    reg        exmem_regwrite;
    reg        exmem_memread;
    reg        exmem_memwrite;
    reg [2:0]  exmem_funct3;
    reg        exmem_valid;

    // =====================================================================
    // MEM/WB pipeline register
    // =====================================================================
    reg [31:0] memwb_mem_data;
    reg [31:0] memwb_alu_result;
    reg [4:0]  memwb_rd;
    reg        memwb_regwrite;
    reg        memwb_memread;   // selects memory data vs ALU result in WB
    reg        memwb_valid;

    // =====================================================================
    // Write-back result (needed by WB write and by ID-stage bypass)
    // =====================================================================
    wire [31:0] wb_result = memwb_memread ? memwb_mem_data : memwb_alu_result;

    // =====================================================================
    // Register file
    // =====================================================================
    reg [31:0] regs [0:31];
    integer    i;

    // =====================================================================
    // ID stage: field extraction
    // =====================================================================
    wire [6:0] id_opcode = ifid_inst[6:0];
    wire [2:0] id_funct3 = ifid_inst[14:12];
    wire [6:0] id_funct7 = ifid_inst[31:25];
    wire [4:0] id_rs1    = ifid_inst[19:15];
    wire [4:0] id_rs2    = ifid_inst[24:20];
    wire [4:0] id_rd     = ifid_inst[11:7];

    // =====================================================================
    // ID stage: register read with write-back bypass
    //   A value produced by the instruction currently in WB must be visible
    //   to the instruction being decoded in this same cycle (write-through),
    //   otherwise the 3-instruction-distance RAW hazard reads stale data.
    // =====================================================================
    wire wb_bypass_rs1 = memwb_valid && memwb_regwrite &&
                         (memwb_rd != 5'd0) && (memwb_rd == id_rs1);
    wire wb_bypass_rs2 = memwb_valid && memwb_regwrite &&
                         (memwb_rd != 5'd0) && (memwb_rd == id_rs2);

    wire [31:0] id_rs1_data = (id_rs1 == 5'd0) ? 32'd0 :
                              (wb_bypass_rs1 ? wb_result : regs[id_rs1]);
    wire [31:0] id_rs2_data = (id_rs2 == 5'd0) ? 32'd0 :
                              (wb_bypass_rs2 ? wb_result : regs[id_rs2]);

    // =====================================================================
    // ID stage: immediate generation
    // =====================================================================
    reg [31:0] id_imm;
    always @(*) begin
        case (id_opcode)
            7'b0010011, 7'b0000011, 7'b1100111: begin
                // I-type
                id_imm = {{20{ifid_inst[31]}}, ifid_inst[31:20]};
            end
            7'b0100011: begin
                // S-type
                id_imm = {{20{ifid_inst[31]}}, ifid_inst[31:25], ifid_inst[11:7]};
            end
            7'b1100011: begin
                // B-type
                id_imm = {{19{ifid_inst[31]}}, ifid_inst[31], ifid_inst[7],
                          ifid_inst[30:25], ifid_inst[11:8], 1'b0};
            end
            7'b1101111: begin
                // J-type
                id_imm = {{11{ifid_inst[31]}}, ifid_inst[31], ifid_inst[19:12],
                          ifid_inst[20], ifid_inst[30:21], 1'b0};
            end
            default: begin
                id_imm = 32'd0;
            end
        endcase
    end

    // =====================================================================
    // ID stage: control decode
    // =====================================================================
    reg        id_regwrite;
    reg        id_memread;
    reg        id_memwrite;
    reg        id_alusrc;
    reg        id_branch;
    reg        id_jump;
    reg        id_jalr;
    reg [3:0]  id_alu_op;

    always @(*) begin
        id_regwrite = 1'b0;
        id_memread  = 1'b0;
        id_memwrite = 1'b0;
        id_alusrc   = 1'b0;
        id_branch   = 1'b0;
        id_jump     = 1'b0;
        id_jalr     = 1'b0;
        id_alu_op   = ALU_ADD;

        case (id_opcode)
            7'b0110011: begin
                // R-type
                id_regwrite = 1'b1;
                case (id_funct3)
                    3'b000:  id_alu_op = id_funct7[5] ? ALU_SUB : ALU_ADD;
                    3'b111:  id_alu_op = ALU_AND;
                    3'b110:  id_alu_op = ALU_OR;
                    3'b100:  id_alu_op = ALU_XOR;
                    3'b010:  id_alu_op = ALU_SLT;
                    3'b001:  id_alu_op = ALU_SLL;
                    3'b101:  id_alu_op = id_funct7[5] ? ALU_SRA : ALU_SRL;
                    default: id_alu_op = ALU_ADD;
                endcase
            end
            7'b0010011: begin
                // I-type ALU
                id_regwrite = 1'b1;
                id_alusrc   = 1'b1;
                case (id_funct3)
                    3'b000:  id_alu_op = ALU_ADD;
                    3'b111:  id_alu_op = ALU_AND;
                    3'b110:  id_alu_op = ALU_OR;
                    3'b100:  id_alu_op = ALU_XOR;
                    3'b010:  id_alu_op = ALU_SLT;
                    3'b001:  id_alu_op = ALU_SLL;
                    3'b101:  id_alu_op = id_funct7[5] ? ALU_SRA : ALU_SRL;
                    default: id_alu_op = ALU_ADD;
                endcase
            end
            7'b0000011: begin
                // LW
                id_regwrite = 1'b1;
                id_memread  = 1'b1;
                id_alusrc   = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            7'b0100011: begin
                // SW
                id_memwrite = 1'b1;
                id_alusrc   = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            7'b1100011: begin
                // Branch
                id_branch = 1'b1;
                id_alu_op = ALU_SUB;
            end
            7'b1101111: begin
                // JAL
                id_regwrite = 1'b1;
                id_jump     = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            7'b1100111: begin
                // JALR
                id_regwrite = 1'b1;
                id_jump     = 1'b1;
                id_jalr     = 1'b1;
                id_alusrc   = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            default: begin
                // NOP / bubble
            end
        endcase
    end

    // =====================================================================
    // Hazard detection (load-use)
    // =====================================================================
    reg stall;
    always @(*) begin
        stall = 1'b0;
        if (idex_valid && idex_memread && (idex_rd != 5'd0) && ifid_valid) begin
            if ((idex_rd == id_rs1) || (idex_rd == id_rs2))
                stall = 1'b1;
        end
    end

    // =====================================================================
    // EX stage: forwarding
    // =====================================================================
    reg [1:0] forward_a;
    reg [1:0] forward_b;

    always @(*) begin
        forward_a = 2'b00;
        if (exmem_valid && exmem_regwrite && !exmem_memread &&
            (exmem_rd != 5'd0) && (exmem_rd == idex_rs1))
            forward_a = 2'b10;
        else if (memwb_valid && memwb_regwrite &&
                 (memwb_rd != 5'd0) && (memwb_rd == idex_rs1))
            forward_a = 2'b01;
        else
            forward_a = 2'b00;
    end

    always @(*) begin
        forward_b = 2'b00;
        if (exmem_valid && exmem_regwrite && !exmem_memread &&
            (exmem_rd != 5'd0) && (exmem_rd == idex_rs2))
            forward_b = 2'b10;
        else if (memwb_valid && memwb_regwrite &&
                 (memwb_rd != 5'd0) && (memwb_rd == idex_rs2))
            forward_b = 2'b01;
        else
            forward_b = 2'b00;
    end

    // Forwarded operands
    reg [31:0] ex_rs1;
    reg [31:0] ex_rs2;

    always @(*) begin
        case (forward_a)
            2'b01:   ex_rs1 = wb_result;
            2'b10:   ex_rs1 = exmem_alu_result;
            default: ex_rs1 = idex_rs1_data;
        endcase
    end

    always @(*) begin
        case (forward_b)
            2'b01:   ex_rs2 = wb_result;
            2'b10:   ex_rs2 = exmem_alu_result;
            default: ex_rs2 = idex_rs2_data;
        endcase
    end

    // =====================================================================
    // EX stage: ALU
    // =====================================================================
    wire [31:0] alu_b = idex_alusrc ? idex_imm : ex_rs2;
    reg  [31:0] alu_out;

    always @(*) begin
        case (idex_alu_op)
            ALU_ADD: alu_out = ex_rs1 + alu_b;
            ALU_SUB: alu_out = ex_rs1 - alu_b;
            ALU_AND: alu_out = ex_rs1 & alu_b;
            ALU_OR:  alu_out = ex_rs1 | alu_b;
            ALU_XOR: alu_out = ex_rs1 ^ alu_b;
            ALU_SLT: alu_out = ($signed(ex_rs1) < $signed(alu_b)) ? 32'd1 : 32'd0;
            ALU_SLL: alu_out = ex_rs1 << alu_b[4:0];
            ALU_SRL: alu_out = ex_rs1 >> alu_b[4:0];
            ALU_SRA: alu_out = $signed(ex_rs1) >>> alu_b[4:0];
            default: alu_out = 32'd0;
        endcase
    end

    // =====================================================================
    // EX stage: branch resolution
    // =====================================================================
    reg branch_cond;
    always @(*) begin
        case (idex_funct3)
            3'b000:  branch_cond = (ex_rs1 == ex_rs2);                     // BEQ
            3'b001:  branch_cond = (ex_rs1 != ex_rs2);                     // BNE
            3'b100:  branch_cond = ($signed(ex_rs1) <  $signed(ex_rs2));   // BLT
            3'b101:  branch_cond = ($signed(ex_rs1) >= $signed(ex_rs2));   // BGE
            default: branch_cond = 1'b0;
        endcase
    end

    reg branch_taken;
    always @(*) begin
        branch_taken = idex_valid && idex_branch && branch_cond;
    end

    wire jump_taken = idex_valid && idex_jump;

    wire [31:0] ex_jump_target   = idex_jalr ? ((ex_rs1 + idex_imm) & 32'hFFFFFFFE)
                                             : (idex_pc + idex_imm);
    wire [31:0] ex_branch_target = idex_pc + idex_imm;
    wire [31:0] redirect_target  = branch_taken ? ex_branch_target : ex_jump_target;

    reg flush;
    always @(*) begin
        flush = branch_taken || jump_taken;
    end

    // Result written back by this instruction (jumps need PC+4)
    wire [31:0] ex_result = idex_jump ? (idex_pc + 32'd4) : alu_out;

    // =====================================================================
    // PC update
    // =====================================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pc <= 32'd0;
        else if (stall)
            pc <= pc;
        else if (flush)
            pc <= redirect_target;
        else
            pc <= pc_plus4;
    end

    // =====================================================================
    // IF/ID pipeline register
    // =====================================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ifid_pc    <= 32'd0;
            ifid_inst  <= 32'h00000013; // NOP
            ifid_valid <= 1'b0;
        end else if (flush) begin
            ifid_pc    <= 32'd0;
            ifid_inst  <= 32'h00000013; // NOP
            ifid_valid <= 1'b0;
        end else if (stall) begin
            ifid_pc    <= ifid_pc;
            ifid_inst  <= ifid_inst;
            ifid_valid <= ifid_valid;
        end else begin
            ifid_pc    <= pc;
            ifid_inst  <= imem_data;
            ifid_valid <= 1'b1;
        end
    end

    // =====================================================================
    // ID/EX pipeline register
    // =====================================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            idex_pc       <= 32'd0;
            idex_rs1_data <= 32'd0;
            idex_rs2_data <= 32'd0;
            idex_rs1      <= 5'd0;
            idex_rs2      <= 5'd0;
            idex_rd       <= 5'd0;
            idex_imm      <= 32'd0;
            idex_regwrite <= 1'b0;
            idex_memread  <= 1'b0;
            idex_memwrite <= 1'b0;
            idex_alusrc   <= 1'b0;
            idex_branch   <= 1'b0;
            idex_jump     <= 1'b0;
            idex_jalr     <= 1'b0;
            idex_alu_op   <= ALU_ADD;
            idex_funct3   <= 3'b000;
            idex_valid    <= 1'b0;
        end else if (flush || stall) begin
            // Insert bubble
            idex_pc       <= 32'd0;
            idex_rs1_data <= 32'd0;
            idex_rs2_data <= 32'd0;
            idex_rs1      <= 5'd0;
            idex_rs2      <= 5'd0;
            idex_rd       <= 5'd0;
            idex_imm      <= 32'd0;
            idex_regwrite <= 1'b0;
            idex_memread  <= 1'b0;
            idex_memwrite <= 1'b0;
            idex_alusrc   <= 1'b0;
            idex_branch   <= 1'b0;
            idex_jump     <= 1'b0;
            idex_jalr     <= 1'b0;
            idex_alu_op   <= ALU_ADD;
            idex_funct3   <= 3'b000;
            idex_valid    <= 1'b0;
        end else begin
            idex_pc       <= ifid_pc;
            idex_rs1_data <= id_rs1_data;
            idex_rs2_data <= id_rs2_data;
            idex_rs1      <= id_rs1;
            idex_rs2      <= id_rs2;
            idex_rd       <= id_rd;
            idex_imm      <= id_imm;
            idex_regwrite <= id_regwrite;
            idex_memread  <= id_memread;
            idex_memwrite <= id_memwrite;
            idex_alusrc   <= id_alusrc;
            idex_branch   <= id_branch;
            idex_jump     <= id_jump;
            idex_jalr     <= id_jalr;
            idex_alu_op   <= id_alu_op;
            idex_funct3   <= id_funct3;
            idex_valid    <= ifid_valid;
        end
    end

    // =====================================================================
    // EX/MEM pipeline register
    // =====================================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            exmem_alu_result <= 32'd0;
            exmem_mem_data   <= 32'd0;
            exmem_rd         <= 5'd0;
            exmem_regwrite   <= 1'b0;
            exmem_memread    <= 1'b0;
            exmem_memwrite   <= 1'b0;
            exmem_funct3     <= 3'b000;
            exmem_valid      <= 1'b0;
        end else begin
            exmem_alu_result <= ex_result;
            exmem_mem_data   <= ex_rs2;
            exmem_rd         <= idex_rd;
            exmem_regwrite   <= idex_regwrite;
            exmem_memread    <= idex_memread;
            exmem_memwrite   <= idex_memwrite;
            exmem_funct3     <= idex_funct3;
            exmem_valid      <= idex_valid;
        end
    end

    // =====================================================================
    // MEM stage
    // =====================================================================
    assign dmem_addr  = exmem_alu_result;
    assign dmem_wdata = exmem_mem_data;
    assign dmem_wen   = exmem_memwrite && exmem_valid;
    assign dmem_be    = 4'b1111;

    // =====================================================================
    // MEM/WB pipeline register
    // =====================================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            memwb_mem_data   <= 32'd0;
            memwb_alu_result <= 32'd0;
            memwb_rd         <= 5'd0;
            memwb_regwrite   <= 1'b0;
            memwb_memread    <= 1'b0;
            memwb_valid      <= 1'b0;
        end else begin
            memwb_mem_data   <= exmem_memread ? dmem_rdata : 32'd0;
            memwb_alu_result <= exmem_alu_result;
            memwb_rd         <= exmem_rd;
            memwb_regwrite   <= exmem_regwrite;
            memwb_memread    <= exmem_memread;
            memwb_valid      <= exmem_valid;
        end
    end

    // =====================================================================
    // WB stage: register file write
    // =====================================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= 32'd0;
        end else if (memwb_valid && memwb_regwrite && (memwb_rd != 5'd0)) begin
            regs[memwb_rd] <= wb_result;
        end
    end

endmodule